-- User-approved rate: 1 EUR = 93 RUB. All monetary columns store integer minor units.
-- Transactional and once-only through Prisma migration history; historical audits stay intact.
BEGIN;
LOCK TABLE "Deal", "Product", "Project", "Expense", "Invoice", "InvoiceItem", "invoice_payments", "Document", "Payment" IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF EXISTS (SELECT currency FROM "Deal" WHERE currency NOT IN ('RUB','EUR') UNION ALL SELECT currency FROM "Product" WHERE currency NOT IN ('RUB','EUR') UNION ALL SELECT currency FROM "Project" WHERE currency NOT IN ('RUB','EUR') UNION ALL SELECT currency FROM "Expense" WHERE currency NOT IN ('RUB','EUR') UNION ALL SELECT currency FROM "Invoice" WHERE currency NOT IN ('RUB','EUR')) THEN RAISE EXCEPTION 'EUR conversion requires a separate approved rate for currencies other than RUB/EUR'; END IF;
 IF EXISTS (SELECT 1 FROM "Expense" WHERE currency='RUB' AND round(amount/93,0)<=0) OR EXISTS(SELECT 1 FROM "invoice_payments" p JOIN "Invoice" i ON i.id=p."invoiceId" AND i."workspaceId"=p."workspaceId" WHERE i.currency='RUB' AND round(p.amount/93,0)<=0) OR EXISTS(SELECT 1 FROM "Payment" WHERE round(amount::numeric/93,0)<=0) THEN RAISE EXCEPTION 'Positive amount cannot be represented in EUR cents at the approved rate'; END IF;
END $$;
CREATE TEMP TABLE old_deal ON COMMIT DROP AS SELECT * FROM "Deal" WHERE currency='RUB';
CREATE TEMP TABLE old_product ON COMMIT DROP AS SELECT * FROM "Product" WHERE currency='RUB';
CREATE TEMP TABLE old_project ON COMMIT DROP AS SELECT * FROM "Project" WHERE currency='RUB';
CREATE TEMP TABLE old_expense ON COMMIT DROP AS SELECT * FROM "Expense" WHERE currency='RUB';
CREATE TEMP TABLE old_invoice ON COMMIT DROP AS SELECT * FROM "Invoice" WHERE currency='RUB';
CREATE TEMP TABLE old_invoiceitem ON COMMIT DROP AS SELECT p.* FROM "InvoiceItem" p JOIN old_invoice i ON i.id=p."invoiceId" AND i."workspaceId"=p."workspaceId";
CREATE TEMP TABLE old_receipt ON COMMIT DROP AS SELECT p.* FROM "invoice_payments" p JOIN old_invoice i ON i.id=p."invoiceId" AND i."workspaceId"=p."workspaceId";
CREATE TEMP TABLE old_document ON COMMIT DROP AS SELECT * FROM "Document";
CREATE TEMP TABLE old_payment ON COMMIT DROP AS SELECT * FROM "Payment";
UPDATE "InvoiceItem" p SET "unitPrice"=round(p."unitPrice"/93,0), total=round(p.quantity*round(p."unitPrice"/93,0),0), version=p.version+1, "updatedAt"=CURRENT_TIMESTAMP FROM old_invoiceitem o WHERE p.id=o.id;
UPDATE "Invoice" i SET currency='EUR', subtotal=s.subtotal, total=round(s.subtotal*(1+i."taxRate"/100),0), version=i.version+1, "updatedAt"=CURRENT_TIMESTAMP FROM (SELECT o.id, COALESCE(SUM(p.total),0) subtotal FROM old_invoice o LEFT JOIN "InvoiceItem" p ON p."invoiceId"=o.id AND p."workspaceId"=o."workspaceId" GROUP BY o.id) s WHERE i.id=s.id;
-- Preserve exact fully-paid/overpaid balance after line-price rounding; reconcile only the last receipt.
WITH totals AS (SELECT o.id, o.total old_total, i.total new_total, SUM(p.amount) old_paid, SUM(round(p.amount/93,0)) converted_paid FROM old_invoice o JOIN "Invoice" i ON i.id=o.id JOIN old_receipt p ON p."invoiceId"=o.id GROUP BY o.id,o.total,i.total), converted AS (SELECT p.id payment_id, round(p.amount/93,0) amount, row_number() OVER(PARTITION BY p."invoiceId" ORDER BY p."createdAt" DESC,p.id DESC) rn, t.* FROM old_receipt p JOIN totals t ON t.id=p."invoiceId")
UPDATE "invoice_payments" p SET amount=c.amount+CASE WHEN c.rn=1 AND c.old_paid>=c.old_total THEN c.new_total+round((c.old_paid-c.old_total)/93,0)-c.converted_paid ELSE 0 END, version=p.version+1,"updatedAt"=CURRENT_TIMESTAMP FROM converted c WHERE p.id=c.payment_id;
-- Do not silently turn partial payments into full payments, or paid invoices into zero-value invoices.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM old_invoice o JOIN "Invoice" i ON i.id=o.id LEFT JOIN (SELECT "invoiceId",SUM(amount) paid FROM old_receipt GROUP BY "invoiceId") a ON a."invoiceId"=o.id LEFT JOIN (SELECT "invoiceId",SUM(amount) paid FROM "invoice_payments" GROUP BY "invoiceId") b ON b."invoiceId"=o.id WHERE (o.total>0 AND i.total=0) OR (COALESCE(a.paid,0)<o.total AND COALESCE(b.paid,0)>=i.total)) THEN RAISE EXCEPTION 'Rounding changes invoice payment classification; review this invoice before conversion'; END IF;
END $$;
UPDATE "Deal" SET "value"=round("value"/93,0), currency='EUR', version=version+1, "updatedAt"=CURRENT_TIMESTAMP WHERE currency='RUB';
UPDATE "Product" SET "costPrice"=round("costPrice"/93,0), "salePrice"=round("salePrice"/93,0), currency='EUR', version=version+1, "updatedAt"=CURRENT_TIMESTAMP WHERE currency='RUB';
UPDATE "Project" SET "budget"=round("budget"/93,0), currency='EUR', version=version+1, "updatedAt"=CURRENT_TIMESTAMP WHERE currency='RUB';
UPDATE "Expense" SET "amount"=round("amount"/93,0), currency='EUR', version=version+1, "updatedAt"=CURRENT_TIMESTAMP WHERE currency='RUB';
UPDATE "Document" SET data=jsonb_set(jsonb_set(data::jsonb,'{amount}',to_jsonb(round(COALESCE((data->>'amount')::numeric,0)/93,0))),'{currency}','"EUR"'::jsonb),version=version+1,"updatedAt"=CURRENT_TIMESTAMP;
UPDATE "Payment" SET amount=round(amount::numeric/93,0)::int;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-Deal-'||o.id,o."workspaceId",'System migration',CASE WHEN 'Deal'='Deal' THEN 'crm' WHEN 'Deal'='Product' THEN 'inventory' WHEN 'Deal'='Project' THEN 'projects' ELSE 'finance' END,'updated','Deal',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('currency','RUB','version',o.version,'value',o."value"::text),jsonb_build_object('currency','EUR','rate','1 EUR = 93 RUB','version',n.version,'value',n."value"::text),CURRENT_TIMESTAMP FROM old_deal o JOIN "Deal" n ON n.id=o.id;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-Product-'||o.id,o."workspaceId",'System migration',CASE WHEN 'Product'='Deal' THEN 'crm' WHEN 'Product'='Product' THEN 'inventory' WHEN 'Product'='Project' THEN 'projects' ELSE 'finance' END,'updated','Product',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('currency','RUB','version',o.version,'costPrice',o."costPrice"::text,'salePrice',o."salePrice"::text),jsonb_build_object('currency','EUR','rate','1 EUR = 93 RUB','version',n.version,'costPrice',n."costPrice"::text,'salePrice',n."salePrice"::text),CURRENT_TIMESTAMP FROM old_product o JOIN "Product" n ON n.id=o.id;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-Project-'||o.id,o."workspaceId",'System migration',CASE WHEN 'Project'='Deal' THEN 'crm' WHEN 'Project'='Product' THEN 'inventory' WHEN 'Project'='Project' THEN 'projects' ELSE 'finance' END,'updated','Project',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('currency','RUB','version',o.version,'budget',o."budget"::text),jsonb_build_object('currency','EUR','rate','1 EUR = 93 RUB','version',n.version,'budget',n."budget"::text),CURRENT_TIMESTAMP FROM old_project o JOIN "Project" n ON n.id=o.id;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-Expense-'||o.id,o."workspaceId",'System migration',CASE WHEN 'Expense'='Deal' THEN 'crm' WHEN 'Expense'='Product' THEN 'inventory' WHEN 'Expense'='Project' THEN 'projects' ELSE 'finance' END,'updated','Expense',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('currency','RUB','version',o.version,'amount',o."amount"::text),jsonb_build_object('currency','EUR','rate','1 EUR = 93 RUB','version',n.version,'amount',n."amount"::text),CURRENT_TIMESTAMP FROM old_expense o JOIN "Expense" n ON n.id=o.id;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-Invoice-'||o.id,o."workspaceId",'System migration',CASE WHEN 'Invoice'='Deal' THEN 'crm' WHEN 'Invoice'='Product' THEN 'inventory' WHEN 'Invoice'='Project' THEN 'projects' ELSE 'finance' END,'updated','Invoice',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('currency','RUB','version',o.version,'subtotal',o."subtotal"::text,'total',o."total"::text),jsonb_build_object('currency','EUR','rate','1 EUR = 93 RUB','version',n.version,'subtotal',n."subtotal"::text,'total',n."total"::text),CURRENT_TIMESTAMP FROM old_invoice o JOIN "Invoice" n ON n.id=o.id;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-InvoiceItem-'||o.id,o."workspaceId",'System migration',CASE WHEN 'InvoiceItem'='Deal' THEN 'crm' WHEN 'InvoiceItem'='Product' THEN 'inventory' WHEN 'InvoiceItem'='Project' THEN 'projects' ELSE 'finance' END,'updated','InvoiceItem',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('currency','RUB','version',o.version,'unitPrice',o."unitPrice"::text,'total',o."total"::text),jsonb_build_object('currency','EUR','rate','1 EUR = 93 RUB','version',n.version,'unitPrice',n."unitPrice"::text,'total',n."total"::text),CURRENT_TIMESTAMP FROM old_invoiceitem o JOIN "InvoiceItem" n ON n.id=o.id;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-invoice_payments-'||o.id,o."workspaceId",'System migration',CASE WHEN 'invoice_payments'='Deal' THEN 'crm' WHEN 'invoice_payments'='Product' THEN 'inventory' WHEN 'invoice_payments'='Project' THEN 'projects' ELSE 'finance' END,'updated','invoice_payments',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('currency','RUB','version',o.version,'amount',o."amount"::text),jsonb_build_object('currency','EUR','rate','1 EUR = 93 RUB','version',n.version,'amount',n."amount"::text),CURRENT_TIMESTAMP FROM old_receipt o JOIN "invoice_payments" n ON n.id=o.id;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-Document-'||o.id,o."workspaceId",'System migration',o.domain,'updated','Document',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('amount',o.data->>'amount','currency','RUB','version',o.version),jsonb_build_object('amount',n.data->>'amount','currency','EUR','version',n.version,'rate','1 EUR = 93 RUB'),CURRENT_TIMESTAMP FROM old_document o JOIN "Document" n ON n.id=o.id;
INSERT INTO "AuditEvent" (id,"workspaceId",actor,domain,action,"entityType","entityId",title,"before","after","createdAt") SELECT 'eur-20261020-Payment-'||o.id,o."workspaceId",'System migration','finance','updated','DocumentPayment',o.id,'Currency conversion: RUB to EUR',jsonb_build_object('amount',o.amount::text,'currency','RUB'),jsonb_build_object('amount',n.amount::text,'currency','EUR','rate','1 EUR = 93 RUB'),CURRENT_TIMESTAMP FROM old_payment o JOIN "Payment" n ON n.id=o.id;
ALTER TABLE "Deal" ALTER COLUMN currency SET DEFAULT 'EUR';
ALTER TABLE "Deal" ADD CONSTRAINT "Deal_eur_currency_check" CHECK(currency='EUR');
ALTER TABLE "Product" ALTER COLUMN currency SET DEFAULT 'EUR';
ALTER TABLE "Product" ADD CONSTRAINT "Product_eur_currency_check" CHECK(currency='EUR');
ALTER TABLE "Project" ALTER COLUMN currency SET DEFAULT 'EUR';
ALTER TABLE "Project" ADD CONSTRAINT "Project_eur_currency_check" CHECK(currency='EUR');
ALTER TABLE "Expense" ALTER COLUMN currency SET DEFAULT 'EUR';
ALTER TABLE "Expense" ADD CONSTRAINT "Expense_eur_currency_check" CHECK(currency='EUR');
ALTER TABLE "Invoice" ALTER COLUMN currency SET DEFAULT 'EUR';
ALTER TABLE "Invoice" ADD CONSTRAINT "Invoice_eur_currency_check" CHECK(currency='EUR');
COMMIT;
